# Let's also try a simpler but potentially more robust approach
# Use iterative deepening with backtracking

def find_is_of_size(k, n, adj):
    """Find independent set of size k using backtracking"""
    vertices = list(range(n))

    def backtrack(start, current_set):
        if len(current_set) == k:
            return list(current_set)

        remaining_needed = k - len(current_set)
        available = n - start
        if available < remaining_needed:
            return None

        for i in range(start, n):
            v = vertices[i]
            # Check if v is compatible with current set
            if all(u not in adj[v] for u in current_set):
                current_set.add(v)
                result = backtrack(i + 1, current_set)
                if result is not None:
                    return result
                current_set.remove(v)

        return None

    return backtrack(0, set())

